  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Voice: Volume, Rate, Pitch and Pause$j$, $j${"readings": [{"title": "Proverbs 15 (King James Version)", "url": "/portal/bible/Proverbs/15"}], "body": "The voice is a speaker's main instrument. Proverbs 15:23 says, A man hath joy by the answer of his mouth: and a word spoken in due season, how good is it! A well used voice carries the message clearly and warmly.\n\nFive qualities of the voice can be shaped. Volume is how loud or soft you speak. Speak loudly enough for the person in the back row, and use a microphone properly when one is provided. Drop the volume at times for emphasis, since a quiet line can be powerful. Rate is the speed of speech. Conversation usually runs about 120 to 150 words per minute. Speaking too fast makes words run together, and too slow can bore the audience. Vary the rate, slowing for key ideas and moving faster in a story. Pitch is how high or low the voice is. A voice with no change in pitch sounds flat, which is called a monotone. Let the pitch rise and fall naturally, as in warm conversation. Tone is the feeling in the voice, such as joy, concern or conviction. Pauses are silent moments that let listeners absorb a point. A pause before a key sentence builds interest, and a pause after it lets it sink in. Do not fear silence.\n\nClear speech depends on articulation and pronunciation. Articulation is shaping sounds with the lips, tongue and teeth, so that endings of words are not dropped. Pronunciation is saying words in the accepted way, so check difficult names and terms before you speak. Practice tongue twisters to warm up the mouth. Breathe from the diaphragm, the muscle below the lungs, and stand tall so the air flows well. Drink water, and avoid shouting before a speech.\n\nFillers such as um, uh, like and you know are common. A few do no harm, but many distract. To reduce them, slow down, pause instead of filling silence, and know your opening and transitions well. Record yourself and listen. Many speakers are surprised at what they hear, and improvement starts with awareness.\n\nYour task: (1) Define volume, rate, pitch, tone and pause. (2) Give the usual speaking rate in words per minute. (3) Describe three ways to reduce filler words.\n\nFlorida standards: Florida speech and communication course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida speech and communication course standards", "script": "Welcome back. Listen, Proverbs 15:23 says, A man hath joy by the answer of his mouth: and a word spoken in due season, how good is it! A well used voice carries the message clearly and warmly.\n\nNow watch this. Volume is how loud you speak. Reach the back row. Drop it at times for emphasis. Rate is speed, and conversation runs about 120 to 150 words per minute. Vary it. Pitch is high or low. Without change it is a monotone. Tone is the feeling in the voice. A pause lets a point sink in. Do not fear silence.\n\nArticulation shapes sounds so word endings are not dropped. Pronunciation is saying words in the accepted way, so check hard names. Breathe from the diaphragm and stand tall. Drink water.\n\nFillers like um and like are common. Slow down. Pause instead of filling the silence. Know your opening and transitions well. Record yourself and listen, because awareness starts improvement.\n\nYour task is to define voice qualities, give the usual rate and describe ways to reduce fillers. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Voice: Volume, Rate, Pitch and Pause$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Body Language, Eye Contact and Presence$j$, $j${"readings": [{"title": "Acts 4 (King James Version)", "url": "/portal/bible/Acts/4"}], "body": "Listeners watch as well as listen. Acts 4:13 says, Now when they saw the boldness of Peter and John, and perceived that they were unlearned and ignorant men, they marvelled; and they took knowledge of them, that they had been with Jesus. Boldness, calm and sincerity show in a speaker's whole presence.\n\nNonverbal delivery includes posture, movement, gestures, facial expression, eye contact and appearance. Posture should be upright but relaxed, with feet about shoulder width apart and weight balanced. Do not lean on the podium or sway. Movement should have a purpose. Step toward the audience to make a point, or move to a new spot at a transition. Avoid pacing without a reason. Gestures should be natural and match the words, such as holding up three fingers for three points or opening the hands to welcome. Avoid distracting habits, such as jingling keys, tugging at clothing or tapping a pen. Keep hands out of pockets and off the podium when you can.\n\nFacial expression should match the message. A smile fits a warm welcome. A serious face fits a hard subject. Many nervous speakers forget to show feeling. Let your face show that you care about what you are saying.\n\nEye contact builds trust. Look at individuals for a few seconds each, sweeping across the room, and avoid staring at the floor, the notes or the screen. Look at people in all parts of the room. Eye contact tells listeners, I am speaking to you.\n\nAppearance matters because it signals respect. Dress to fit the occasion and the audience, and be neat and modest. In many settings, dress one step more formally than the audience. Wear comfortable clothing that does not draw attention away from your message.\n\nPresence is the sum of these things. It comes from preparation, sincerity and care for the audience. Different cultures read gestures and eye contact in different ways, so a thoughtful speaker pays attention to the people present. Above all, let your life match your words. 1 Timothy 4:12 says, Let no man despise thy youth; but be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity.\n\nYour task: (1) List six parts of nonverbal delivery. (2) Describe how to use eye contact well. (3) Explain what Acts 4:13 teaches about presence.\n\nFlorida standards: Florida speech and communication course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida speech and communication course standards", "script": "Welcome back. Listen, Acts 4:13 says, Now when they saw the boldness of Peter and John, and perceived that they were unlearned and ignorant men, they marvelled; and they took knowledge of them, that they had been with Jesus. Boldness, calm and sincerity show in a speaker's whole presence.\n\nNow watch this. Nonverbal delivery includes posture, movement, gestures, facial expression, eye contact and appearance. Stand upright but relaxed, feet shoulder width apart. Move with purpose, not pacing. Make gestures natural, like three fingers for three points. Avoid jingling keys, tugging clothes or tapping a pen. Let your face match your message.\n\nEye contact builds trust. Look at individuals for a few seconds each and sweep across the room. Do not stare at the floor, the notes or the screen.\n\nAppearance signals respect. Dress to fit the occasion, neat and modest. Presence comes from preparation, sincerity and care for the audience. Cultures read gestures and eye contact differently, so pay attention to the people present.\n\nLet your life match your words. 1 Timothy 4:12 says, be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity.\n\nYour task is to list nonverbal parts, use eye contact and explain presence. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Body Language, Eye Contact and Presence$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Practice, Notes and Handling Mistakes$j$, $j${"readings": [{"title": "2 Timothy 2 (King James Version)", "url": "/portal/bible/2Timothy/2"}], "body": "Great speakers are made in practice. 2 Timothy 2:15 says, Study to shew thyself approved unto God, a workman that needeth not to be ashamed, rightly dividing the word of truth. Diligence in preparation is a form of respect for God and for the people who listen.\n\nThere are four common ways to deliver a speech. A manuscript speech is read word for word. It is exact but can sound stiff, and it cuts eye contact. A memorized speech is recited from memory. It can look polished, but a lapse can cause panic. An impromptu speech is given with little or no preparation, such as answering a question in class. An extemporaneous speech is carefully prepared and practiced, but delivered from a brief outline in natural words. This is the style most speakers use because it is both organized and conversational.\n\nPractice in stages. First, read your outline and say the speech aloud, even if it is rough. Second, practice standing, with your notes, and time it. Aim to land within the time limit, and if you are over, cut material and do not speed up. Third, practice in front of a mirror, a recording or a trusted listener such as a parent, friend or youth leader, and ask for specific feedback. Fourth, practice the opening and closing until they are smooth. Practice at least three or four times in the days before, not all in one night. Rest well, eat, and arrive early to check the room.\n\nMistakes will happen. A forgotten word, a cough or a technical glitch is usually not a disaster. If you lose your place, pause, breathe, look at your notes and continue. Do not apologize at length. If a fact was wrong, correct it briefly and move on. If a distraction occurs, such as a noise or a late arrival, pause and carry on calmly or use a light remark. Audiences judge a speaker by how they recover. Humble honesty wins respect.\n\nAfter a speech, ask for feedback and reflect. Note what worked and choose one skill to improve next time. Proverbs 12:1 says, Whoso loveth instruction loveth knowledge.\n\nYour task: (1) Compare manuscript, memorized, impromptu and extemporaneous delivery. (2) Describe four stages of practice. (3) Tell what to do when you lose your place.\n\nFlorida standards: Florida speech and communication course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida speech and communication course standards", "script": "Welcome back. Listen, 2 Timothy 2:15 says, Study to shew thyself approved unto God, a workman that needeth not to be ashamed, rightly dividing the word of truth. Diligence in preparation is respect for God and for those who listen.\n\nNow watch this. A manuscript speech is read word for word. It is exact but can sound stiff. A memorized speech can look polished, but a lapse causes panic. An impromptu speech has little preparation. An extemporaneous speech is carefully practiced but delivered from a brief outline in natural words. Most speakers use this style.\n\nPractice in stages. Say the speech aloud. Practice standing, with notes, and time it. If you are over, cut material, do not speed up. Practice before a trusted listener and ask for specific feedback. Polish the opening and closing. Practice three or four times in the days before, not all in one night. Rest, eat and arrive early.\n\nMistakes happen. If you lose your place, pause, breathe, look at your notes and continue. Do not apologize at length. Correct a wrong fact briefly. Audiences judge how you recover.\n\nAfterward, ask for feedback and choose one skill to improve. Proverbs 12:1 says, Whoso loveth instruction loveth knowledge.\n\nYour task is to compare delivery styles, describe practice stages and tell what to do when you lose your place. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Practice, Notes and Handling Mistakes$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Visual Aids and Technology$j$, $j${"readings": [{"title": "Habakkuk 2 (King James Version)", "url": "/portal/bible/Habakkuk/2"}], "body": "A picture can make an idea clear in a moment. Habakkuk 2:2 says, Write the vision, and make it plain upon tables, that he may run that readeth it. Visual aids make a message plain, but they must serve the speech and not take it over.\n\nVisual aids come in many forms. Objects and models let the audience see the real thing. Charts and graphs show numbers and trends. Diagrams explain how something works. Photographs and short video clips show places and events. Slides combine text and images. A handout gives details to take home. Choose a visual only if it helps the audience understand or remember. If it does not, leave it out.\n\nGood slides follow simple rules. Use one main idea per slide. Use few words, with large, easy to read type of at least 24 points for body text and plain fonts. Use strong contrast, such as dark text on a light background or light text on a dark one. Use pictures and charts rather than paragraphs. Label charts clearly and show only the data that matters. Be consistent in color and style across slides. Do not read your slides aloud word for word. The slides support you, and you are the speaker. Credit the source of images and data, and use only images you have permission to use.\n\nWhen using a visual, talk to the audience and not to the screen. Stand beside the screen, point briefly, then turn back. Show the visual when you talk about it, and hide it afterward so that it does not distract. Do not pass objects around during the speech, since people will stop listening.\n\nTechnology can fail. Test the equipment before the audience arrives. Know how to advance slides and adjust the sound. Save your file in two places and bring a backup, such as a copy on a drive or a printout of the slides. Have a plan to give the speech without the slides if needed. Microphones should be tested, and you should keep your mouth about a hand's width from a handheld microphone. A speaker who prepares for trouble can stay calm if trouble comes.\n\nYour task: (1) Name four kinds of visual aids. (2) List five rules for good slides. (3) Describe a backup plan for technology.\n\nFlorida standards: Florida speech and communication course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida speech and communication course standards", "script": "Welcome back. Listen, Habakkuk 2:2 says, Write the vision, and make it plain upon tables, that he may run that readeth it. Visual aids make a message plain, but they must serve the speech and not take it over.\n\nNow watch this. Visuals include objects, models, charts, graphs, diagrams, photographs, video clips, slides and handouts. Choose a visual only if it helps understanding or memory.\n\nGood slides use one main idea per slide, few words, large plain type, strong contrast, pictures and charts instead of paragraphs, and consistent style. Do not read slides word for word. Credit sources and use only images you have permission to use.\n\nTalk to the audience, not the screen. Stand beside it, point briefly and turn back. Show the visual when you talk about it and hide it afterward. Do not pass objects around.\n\nTechnology can fail. Test equipment early. Save your file in two places. Bring a backup. Be ready to speak without slides. Keep a handheld microphone about a hand's width from your mouth.\n\nYour task is to name visual aids, list slide rules and describe a backup plan. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Visual Aids and Technology$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Delivering a Speech$j$, $j${"prompt": "Write a report of at least 250 words on delivery. Use complete sentences and label each part. Proverbs 15:23 says, A man hath joy by the answer of his mouth: and a word spoken in due season, how good is it!\n\nPart 1: Define volume, rate, pitch, tone, pause, articulation and pronunciation. Give the usual speaking rate, explain what a monotone is, and list three ways to reduce filler words.\nPart 2: Describe six parts of nonverbal delivery, explain how to use eye contact, and explain what Acts 4:13 shows about a speaker's presence.\nPart 3: Compare manuscript, memorized, impromptu and extemporaneous delivery. Explain which style you would use for a five minute speech and why.\nPart 4: Write a practice plan for the week before a speech with at least four steps, and describe what you will do if you lose your place or a technology problem occurs.\nPart 5: Choose one visual aid for a speech topic, describe it, and explain five rules you will follow in using it. Explain how Habakkuk 2:2 and 2 Timothy 2:15 apply to delivery.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 15 points. Part 4: 20 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Delivering a Speech$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: A Word in Due Season$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a speaker you have heard whose delivery you admired and what made it effective, (2) explains in your own words one voice or body language skill you want to improve, (3) explains why sincerity and preparation matter more than showmanship, and (4) connects your answer to Proverbs 15:23, Acts 4:13 or 2 Timothy 2:15. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can a speaker be confident without being proud? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: A Word in Due Season$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Voice: Volume, Rate, Pitch and Pause$j$, $j${"questions": [{"q": "A voice that does not change in pitch sounds:", "options": ["Articulate", "Emphatic", "Monotone", "Animated"]}, {"q": "Conversation usually runs about how many words per minute?", "options": ["500 to 600", "20 to 40", "300 to 400", "120 to 150"]}, {"q": "A pause before or after a key idea helps by:", "options": ["Letting listeners absorb the point", "Hiding mistakes", "Wasting time", "Showing fear"]}, {"q": "Shaping sounds clearly with the lips, tongue and teeth is:", "options": ["Volume", "Rate", "Articulation", "Pitch"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Voice: Volume, Rate, Pitch and Pause$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,2}'::int[], array[$j$Monotone means a single flat tone.$j$,$j$That range sounds natural and clear.$j$,$j$Silence gives emphasis.$j$,$j$Good articulation keeps word endings clear.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Voice: Volume, Rate, Pitch and Pause$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Body Language, Eye Contact and Presence$j$, $j${"questions": [{"q": "Good eye contact means:", "options": ["Looking at individuals across the room for a few seconds each", "Staring at the floor", "Looking only at one friend", "Reading the screen only"]}, {"q": "Gestures should be:", "options": ["Constant and random", "Natural and matched to the words", "Distracting", "Hidden"]}, {"q": "Which is a distracting habit?", "options": ["Jingling keys or tapping a pen", "Smiling at a welcome", "Standing upright", "Pausing"]}, {"q": "Appearance matters for a speaker because it:", "options": ["Decides the topic", "Signals respect for the audience and occasion", "Replaces preparation", "Is never noticed"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Body Language, Eye Contact and Presence$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,0,1}'::int[], array[$j$It tells listeners you are speaking to them.$j$,$j$Purposeful gestures support the message.$j$,$j$Nervous habits pull attention away.$j$,$j$Fitting dress shows respect.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Body Language, Eye Contact and Presence$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Practice, Notes and Handling Mistakes$j$, $j${"questions": [{"q": "A speech that is carefully prepared and practiced but delivered from brief notes is:", "options": ["Extemporaneous", "Manuscript", "Impromptu", "Memorized"]}, {"q": "If you run over the time limit while practicing, you should:", "options": ["Speak faster", "Cut material", "Skip the conclusion", "Add more points"]}, {"q": "If you lose your place during a speech, the best response is to:", "options": ["Apologize for five minutes", "Run out of the room", "Pause, breathe, check your notes and continue", "Start over loudly"]}, {"q": "A speech given with little or no preparation is:", "options": ["Manuscript", "Extemporaneous", "Memorized", "Impromptu"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Practice, Notes and Handling Mistakes$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,2,3}'::int[], array[$j$Extemporaneous speaking is organized yet conversational.$j$,$j$Trim content and keep a steady pace.$j$,$j$A calm recovery earns respect.$j$,$j$Impromptu means without preparation.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Practice, Notes and Handling Mistakes$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Visual Aids and Technology$j$, $j${"questions": [{"q": "A good slide should have:", "options": ["Paragraphs of small text", "One main idea and few words", "No pictures ever", "Clashing colors"]}, {"q": "When using a visual aid, a speaker should:", "options": ["Pass objects around", "Turn their back", "Read the slide silently", "Talk to the audience, not to the screen"]}, {"q": "The best backup plan for technology is to:", "options": ["Save the file in two places and be ready to speak without slides", "Blame the equipment", "Hope for the best", "Skip testing"]}, {"q": "Before using a visual aid, a speaker should ask:", "options": ["Does it help the audience understand or remember?", "Is it long?", "Is it loud?", "Is it colorful?"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Visual Aids and Technology$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,0,0}'::int[], array[$j$Simple slides support the speaker.$j$,$j$Keep your attention on the people.$j$,$j$Preparation keeps you calm if something fails.$j$,$j$A visual must serve the message.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Visual Aids and Technology$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Delivering a Speech$j$, $j${"questions": [{"q": "The speed of speech is called:", "options": ["Articulation", "Rate", "Tone", "Pitch"]}, {"q": "A pause before an important sentence helps to:", "options": ["Build interest and let the point sink in", "Hide the topic", "Waste time", "Show fear"]}, {"q": "Which is a filler word?", "options": ["Therefore", "Finally", "Next", "Um"]}, {"q": "Standing with feet about shoulder width apart gives:", "options": ["A distracting sway", "A stiff look", "A balanced, steady posture", "A sleepy look"]}, {"q": "An extemporaneous speech is:", "options": ["Given with no preparation", "Read word for word", "Recited from memory", "Practiced and delivered from brief notes"]}, {"q": "The best way to stay within the time limit is to:", "options": ["Skip the conclusion", "Speak faster", "Practice with a timer and cut material if needed", "Ignore the time"]}, {"q": "Body text on a slide should be at least about:", "options": ["8 points", "24 points", "2 points", "4 points"]}, {"q": "Habakkuk 2:2 teaches a speaker to:", "options": ["Hide the message", "Make it complicated", "Make the message plain", "Speak without a message"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Delivering a Speech$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,3,2,3,2,1,2}'::int[], array[$j$Rate is how fast you speak.$j$,$j$Silence adds emphasis.$j$,$j$Fillers are empty sounds or words.$j$,$j$Balanced posture supports calm delivery.$j$,$j$It blends planning and natural words.$j$,$j$Trimming content is better than rushing.$j$,$j$Large type is easy to read from the back.$j$,$j$Clear communication serves the listener.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Delivering a Speech$j$ on conflict (item_id) do nothing;
